mapper.select:
SELECT id, tenant_id, provider_code, issuer_hash, subject_hash, subject_hint, user_id,
       status, last_authenticated_at, del_flag,
       create_by, create_time, create_dept, update_by, update_time
FROM ai_capability_external_identity
WHERE tenant_id = #{tenantId}
  AND provider_code = #{providerCode}
  AND issuer_hash = #{issuerHash}
  AND subject_hash = #{subjectHash}
  AND status = 'ENABLED'
  AND del_flag = 0
LIMIT 1

mapper.update:
UPDATE ai_capability_external_identity
SET last_authenticated_at = #{authenticatedAt}, update_time = NOW()
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND status = 'ENABLED'
  AND del_flag = 0

UPDATE ai_capability_external_identity
SET status = 'DISABLED', del_flag = id, update_time = NOW()
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND provider_code = #{providerCode}
  AND issuer_hash = #{issuerHash}
  AND status = 'ENABLED'
  AND del_flag = 0
